  "create-an-account-or-log-in-with-the-service-tha": {
    "de": "Erstelle ein Konto oder melde Dich mit dem Dienst an, den Du an Deiner Schule nutzt. Wenn der Dienst, den Du normalerweise nutzt, nicht zu den Optionen gehört, bitte Deine Lehrkraft, sich an koordination.power.feedback@uni-rostock.de zu wenden.",
    "en": "Create an account or log in with the Service that you use at your school. If the Service you normally use is not among the options, please ask your teacher to contact edu.pila@oecd.org.",
    "es": "Cree una cuenta o inicie sesión en el Servicio que utiliza en su escuela. Si el Servicio que utiliza normalmente no está entre las opciones, pídale a su maestro que se comunique con edu.pila@oecd.org.",
    "fr": "Créez un compte ou connectez-vous avec le service que vous utilisez dans votre école. Si le service que vous utilisez habituellement ne figure pas parmi les options, veuillez demander à votre enseignant de contacter pila_france@povertyactionlab.org.",
    "km": "បង្កើតគណនី ឬចូលប្រើដោយសេវាដែលអ្នកប្រើនៅសាលា។ ប្រសិនបើសេវាដែលអ្នកប្រើប្រចាំមិនមានក្នុងជម្រើស សូមស្នើឲ្យគ្រូរបស់អ្នកទំនាក់ទំនងទៅ edu.pila@oecd.org។",
    "lv": "Izveidojiet kontu vai piesakieties pakalpojumā, ko izmantojat savā skolā. Ja pakalpojums, kuru parasti izmantojat, nav pieejams, lūdziet savam skolotājam sazināties ar dace.rutina@lu.lv.",
    "nl": "Maak een account aan of log in met de Dienst die u op uw school gebruikt. Als de dienst die u normaal gebruikt niet tot de mogelijkheden behoort, kunt u uw docent vragen contact op te nemen met edu.pila@oecd.org.",
    "pl": "Utwórz konto lub zaloguj się za pomocą usługi, której używasz w swojej szkole. Jeśli usługa, której zwykle używasz, nie jest dostępna, poproś nauczyciela o kontakt z edu.pila@oecd.org.",
    "pt": "Crie uma conta ou faça login com o serviço que você utiliza na sua escola. Se o serviço que você normalmente usa não estiver entre as opções, por favor, peça ao seu professor que entre em contato com edu.pila@oecd.org.",
    "sk": "Vytvor si účet alebo sa prihlás pomocou služby, ktorú používaš vo svojej škole. Ak služba, ktorú bežne používaš, nie je medzi možnosťami, požiadaj svojho učiteľa/ku, aby kontaktoval/a aitutor@minedu.sk.",
    "th": "สร้างบัญชีหรือเข้าสู่ระบบด้วยบริการที่คุณใช้ในโรงเรียนของคุณ หากบริการที่คุณใช้ปกติไม่อยู่ในตัวเลือก กรุณาขอให้ครูของคุณติดต่อ edu.pila@oecd.org"
  },
