  "if-you-opt-out-you-will-no-longer-be-included-in": {
    "de": "Wenn Sie sich abmelden, werden Sie nicht mehr an experimentellen Funktionen oder A/B-Tests teilnehmen, die mit diesem Konto verknüpft sind. \n\nSie haben weiterhin normalen Zugriff, neue experimentelle Änderungen werden Ihnen jedoch möglicherweise nicht angezeigt.",
    "en": "If you opt out, you will no longer be included in experimental features or A/B tests tied to this account.\n\nYou will continue to have normal access, but new experimental changes may not be shown to you.",
    "es": "Si opta por no participar, ya no se le incluirá en las funciones experimentales ni en las pruebas A/B vinculadas a esta cuenta. \n\nContinuará teniendo acceso normal, pero es posible que no se le muestren nuevos cambios experimentales.",
    "fr": "Si vous vous retirez, vous ne serez plus inclus dans les fonctionnalités expérimentales ou les tests A/B liés à ce compte. Vous conserverez un accès normal, mais les nouvelles modifications expérimentales peuvent ne pas vous être affichées.",
    "km": "ប្រសិនបើអ្នកបោះបង់ អ្នកនឹងមិនត្រូវរួមបញ្ចូលក្នុងលក្ខណៈពិសោធន៍ ឬការធ្វើតេស្ត A/B ដែលភ្ជាប់ជាមួយគណនីនេះទៀតទេ។ អ្នកនៅតែអាចចូលប្រើតាមធម្មតាបាន ប៉ុន្តែការផ្លាស់ប្តូរពិសោធន៍ថ្មីៗអាចមិនត្រូវបង្ហាញឱ្យអ្នកឃើញទេ។",
    "lv": "Ja atteiksities, jūs vairs netiksiet iekļauts eksperimentālajās aktivitātēs vai A/B testos, kas ir saistīti ar šo kontu. \n\nJums joprojām būs parasta piekļuve, taču jaunas pētījuma izmaiņas var netikt rādītas.",
    "nl": "Als u zich afmeldt, wordt u niet langer opgenomen in experimentele functies of A/B-tests die aan dit account zijn gekoppeld. \n\nU behoudt de normale toegang, maar nieuwe experimentele wijzigingen worden mogelijk niet aan u getoond.",
    "pl": "Jeśli zrezygnujesz, nie będziesz już uwzględniany w funkcjach eksperymentalnych ani testach A/B powiązanych z tym kontem. Nadal będziesz mieć normalny dostęp, ale nowe eksperymentalne zmiany mogą nie być ci pokazywane.",
    "pt": "Se você cancelar, não será mais incluído em recursos experimentais ou testes A/B vinculados a esta conta. \n\nVocê continuará tendo acesso normal, mas novas alterações experimentais talvez não sejam mostradas para você.",
    "sk": "Ak sa odhlásite, už nebudete súčasťou experimentálnych funkcií ani A/B testov spojených s týmto účtom. \n\nNaďalej budete mať normálny prístup, ale nové experimentálne zmeny sa vám nemusia zobraziť.",
    "th": "หากคุณยกเลิก คุณจะไม่ถูกรวมอยู่ในคุณลักษณะทดลองหรือการทดสอบ A/B ที่เชื่อมโยงกับบัญชีนี้อีกต่อไป คุณยังคงสามารถเข้าถึงตามปกติได้ แต่การเปลี่ยนแปลงการทดลองใหม่อาจไม่แสดงให้คุณเห็น"
  },
